import { execSync } from 'node:child_process';

async function main() {
  const apiKey = process.env.GEMINI_API_KEY;
  let prNumber = process.env.PR_NUMBER;
  if (!prNumber) {
    try {
      prNumber = execSync(`gh pr view --json number -q .number`, { encoding: 'utf-8' }).trim();
    } catch {
      // ignore
    }
  }

  const baseRef = process.env.BASE_REF || 'develop';

  if (!apiKey) {
    console.warn('⚠️ GEMINI_API_KEY is not set in GitHub repository secrets. Skipping automated summary generation.');
    process.exit(0);
  }

  if (!prNumber) {
    console.error('❌ PR_NUMBER environment variable is missing and could not be detected from branch.');
    process.exit(1);
  }

  console.log(`🔍 Inspecting PR #${prNumber} diff against base branch: origin/${baseRef}...`);

  // 1. Get current PR title and existing body
  let existingBody = '';
  let prTitle = '';
  try {
    const prJson = execSync(`gh pr view ${prNumber} --json title,body`, { encoding: 'utf-8' });
    const prData = JSON.parse(prJson);
    prTitle = prData.title || '';
    existingBody = (prData.body || '').trim();
  } catch (err) {
    console.warn('Could not read existing PR details via gh CLI, proceeding with empty body.', err.message);
  }

  // 2. Extract git diff excluding lockfiles and build artifacts
  let diff = '';
  try {
    diff = execSync(
      `git diff --stat origin/${baseRef}...HEAD && echo "---" && git diff origin/${baseRef}...HEAD -- . ':!package-lock.json' ':!*.lock' ':!dist' ':!build'`,
      { encoding: 'utf-8', maxBuffer: 10 * 1024 * 1024 }
    );
  } catch (err) {
    console.error('Failed to extract git diff:', err.message);
    process.exit(1);
  }

  // Cap diff length to prevent token limits on large PRs
  const maxDiffLength = 30000;
  if (diff.length > maxDiffLength) {
    diff = diff.slice(0, maxDiffLength) + '\n\n[... diff truncated for AI summarization ...]';
  }

  if (!diff.trim()) {
    console.log('No meaningful code changes detected in diff. Skipping summary.');
    process.exit(0);
  }

  // 3. Prepare AI prompt
  const systemPrompt = `You are a software engineer writing a clean, professional Pull Request description for the esteRoute repository.
Given the PR Title and Git Diff, generate a high-quality, human-grade pull request description.

Strict Guidelines:
- DO NOT use any emojis anywhere (no robot icons, rockets, sparkles, or emoji bullet points). Keep it strictly professional.
- DO NOT mention that this was generated by AI or an automated system. Write naturally from the perspective of the developer submitting the PR.
- DO NOT include conversational filler like "Here is the description". Output only the Markdown content.

Structure the output as follows:

## Overview
A concise 2-3 sentence explanation of what this pull request does and the problem it solves.

## Key Changes
Group changes by area (e.g., ### Frontend, ### Backend, ### CI / Infrastructure):
- Bullet points explaining specific functional and architectural modifications.

## Verification
- List of tests, checks, or verification steps performed (e.g. linting, build, manual UI testing).

PR Title: ${prTitle}

Git Diff & Stats:
${diff}
`;

  // 4. Call Gemini API
  console.log('Requesting PR summary from Gemini API...');
  let aiSummary = '';

  // Explicitly prefer clean, stable text models
  let modelsToTry = [
    'gemini-flash-latest',
    'gemini-3.8-flash',
    'gemini-2.5-flash-lite',
    'gemini-flash-lite-latest'
  ];

  try {
    const listRes = await fetch(`https://generativelanguage.googleapis.com/v1beta/models?key=${apiKey}`, {
      signal: AbortSignal.timeout(8000)
    });
    if (listRes.ok) {
      const listData = await listRes.json();
      const availableTextModels = (listData.models || [])
        .filter(m => m.supportedGenerationMethods?.includes('generateContent'))
        .map(m => m.name.replace(/^models\//, ''))
        // Filter OUT audio, tts, embedding, and non-text models
        .filter(name => !name.includes('tts') && !name.includes('audio') && !name.includes('embed') && !name.includes('realtime'));

      // Look for preferred models in order
      const candidates = [
        'gemini-flash-latest',
        'gemini-3.8-flash',
        'gemini-2.5-flash-lite',
        'gemini-flash-lite-latest',
        ...availableTextModels.filter(m => m.includes('flash') && !m.includes('preview') && !m.includes('2.5-flash'))
      ];

      // Deduplicate and limit to top 3 valid models
      modelsToTry = Array.from(new Set(candidates.filter(m => availableTextModels.includes(m) || m === 'gemini-flash-latest'))).slice(0, 3);
      console.log(`Targeting Gemini models: ${modelsToTry.join(', ')}`);
    }
  } catch (err) {
    console.warn('Could not query model list dynamically, using defaults:', err.message);
  }

  for (const model of modelsToTry) {
    try {
      console.log(`Attempting generation with ${model}...`);
      const url = `https://generativelanguage.googleapis.com/v1beta/models/${model}:generateContent?key=${apiKey}`;
      const response = await fetch(url, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        signal: AbortSignal.timeout(25000),
        body: JSON.stringify({
          contents: [{ parts: [{ text: systemPrompt }] }],
          generationConfig: {
            temperature: 0.2,
            maxOutputTokens: 8192
          }
        })
      });

      if (!response.ok) {
        const errorText = await response.text();
        console.warn(`Model ${model} returned error status ${response.status}:`, errorText);
        continue;
      }

      const data = await response.json();
      const candidate = data?.candidates?.[0];
      if (candidate?.finishReason && candidate.finishReason !== 'STOP') {
        console.warn(`Model ${model} finished with reason: ${candidate.finishReason}`);
      }

      aiSummary = candidate?.content?.parts?.[0]?.text;
      if (aiSummary) {
        console.log(`Successfully generated full summary using ${model}.`);
        break;
      }
    } catch (apiErr) {
      console.warn(`Request failed for ${model}:`, apiErr.message);
    }
  }

  if (!aiSummary) {
    console.error('Failed to generate summary from Gemini API with available models.');
    process.exit(1);
  }

  // 5. Assemble final PR body
  // If user already wrote custom notes, preserve them at the top without AI branding
  let finalBody = '';
  const marker = '## Overview';

  if (existingBody && !existingBody.includes(marker)) {
    finalBody = `${existingBody}\n\n---\n\n${aiSummary.trim()}`;
  } else {
    finalBody = aiSummary.trim();
  }

  // 6. Update PR via gh CLI
  console.log('Updating PR description...');
  try {
    // Write body to temporary file to safely handle quotes and multiline formatting
    const fs = await import('node:fs');
    const path = await import('node:path');
    const tempFile = path.resolve('.pr_body_temp.md');
    fs.writeFileSync(tempFile, finalBody, 'utf-8');

    execSync(`gh pr edit ${prNumber} --body-file "${tempFile}"`, { encoding: 'utf-8' });
    fs.unlinkSync(tempFile);

    console.log(`Pull Request #${prNumber} description updated successfully.`);
  } catch (updateErr) {
    console.error('Failed to update PR description via gh CLI:', updateErr.message);
    process.exit(1);
  }
}

main().catch((err) => {
  console.error('Unexpected error in PR summary script:', err);
  process.exit(1);
});
